/* 齿轮工坊：理想外啮合运动学。无外部依赖，可在浏览器和 Node 中运行。 */
(function(root){'use strict';
const M=4,TAU=Math.PI*2,TEETH=[20,30,40,60];
const radius=z=>M*z/2;
function topology(gears){const edges=[],overlaps=[];for(let i=0;i<gears.length;i++)for(let j=i+1;j<gears.length;j++){const a=gears[i],b=gears[j],distance=Math.hypot(b.x-a.x,b.y-a.y),ideal=radius(a.z)+radius(b.z);if(distance<ideal-2)overlaps.push([a.id,b.id]);else if(Math.abs(distance-ideal)<=2)edges.push([a.id,b.id]);}return{edges,overlaps};}
function solve(gears,motor,phase=0){const {edges,overlaps}=topology(gears),map=new Map(gears.map(g=>[g.id,g])),ratios={},angles={},conflicts=[];if(!map.has(motor))return{edges,overlaps,ratios,angles,conflicts};ratios[motor]=1;angles[motor]=phase;const q=[motor];for(let i=0;i<q.length;i++){const a=map.get(q[i]);for(const e of edges){const id=e[0]===a.id?e[1]:e[1]===a.id?e[0]:null;if(!id)continue;const b=map.get(id),v=-ratios[a.id]*a.z/b.z,phi=Math.atan2(b.y-a.y,b.x-a.x);if(id in ratios){if(Math.abs(ratios[id]-v)>1e-8)conflicts.push(e);}else{ratios[id]=v;angles[id]=((a.z+b.z)*phi+b.z*Math.PI-Math.PI-a.z*angles[a.id])/b.z;q.push(id);}}}return{edges,overlaps,ratios,angles,conflicts};}
function snap(g,others,threshold=27){let best=null;for(const h of others){const dx=g.x-h.x,dy=g.y-h.y,d=Math.hypot(dx,dy),r=radius(g.z)+radius(h.z),error=Math.abs(d-r);if(d<1||error>threshold)continue;const candidate={...g,x:h.x+dx/d*r,y:h.y+dy/d*r};if(others.some(o=>o.id!==h.id&&Math.hypot(candidate.x-o.x,candidate.y-o.y)<radius(g.z)+radius(o.z)-2))continue;if(!best||error<best.error)best={...candidate,error};}return best?{...g,x:best.x,y:best.y}:g;}
function gearPath(z){const r=radius(z),rootR=r-1.25*M,tip=r+M,base=r*Math.cos(20*Math.PI/180),start=Math.max(rootR,base),inv=a=>Math.tan(a)-a,invPitch=inv(20*Math.PI/180),half=Math.PI/(2*z),point=(rr,a)=>`${(rr*Math.cos(a)).toFixed(3)},${(rr*Math.sin(a)).toFixed(3)}`;const pts=[];for(let i=0;i<z;i++){const center=i*TAU/z;const flank=rr=>half+invPitch-inv(Math.acos(Math.min(1,base/rr)));pts.push(point(rootR,center-flank(start)));for(let k=0;k<=5;k++){const rr=start+(tip-start)*k/5;pts.push(point(rr,center-flank(rr)));}for(let k=5;k>=0;k--){const rr=start+(tip-start)*k/5;pts.push(point(rr,center+flank(rr)));}pts.push(point(rootR,center+flank(start)));}return'M'+pts.join('L')+'Z';}
function validateDesign(data){if(!data||data.format!=='gear-workshop-v1'||!Array.isArray(data.gears)||data.gears.length<1||data.gears.length>12)throw Error('不是有效的齿轮工坊设计文件。');const ids=new Set;for(const g of data.gears){if(typeof g.id!=='string'||!/^[A-Z]$/.test(g.id)||ids.has(g.id)||!TEETH.includes(g.z)||!Number.isFinite(g.x)||!Number.isFinite(g.y)||g.x<radius(g.z)+8||g.x>1000-radius(g.z)-8||g.y<radius(g.z)+8||g.y>600-radius(g.z)-8)throw Error('文件中的齿轮参数不合法。');ids.add(g.id);}if(!ids.has(data.motor)||!ids.has(data.output))throw Error('文件缺少有效的输入或输出轮。');return{gears:data.gears.map(g=>({id:g.id,z:g.z,x:g.x,y:g.y})),motor:data.motor,output:data.output,speed:Math.max(5,Math.min(60,Number(data.speed)||20)),direction:data.direction===-1?-1:1};}
const api={M,TAU,TEETH,radius,topology,solve,snap,gearPath,validateDesign};if(typeof module!=='undefined'&&module.exports)module.exports=api;else root.GearCore=api;
})(typeof window!=='undefined'?window:globalThis);
